"""Observational comparison of two already validated snapshot projections."""
from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class SnapshotComparison:
    left_snapshot_id:str; right_snapshot_id:str; left_generated_as_of:str; right_generated_as_of:str; chronological_order:str; same_release:bool; same_implementation_digest:bool; operational_status_change:bool; readiness_status_change:bool; operator_action_change:bool; evidence_completeness_change:bool; evidence_freshness_change:bool; suspension_change:bool; heartbeat_change:bool; alert_change:bool; acknowledgment_change:bool; recovery_change:bool; blockers_added:tuple[str,...]; blockers_removed:tuple[str,...]; component_changes:tuple[tuple[str,str,str],...]; safety_invariants_unchanged:bool; permits_automated_action:bool; live_ready:bool; unattended_ready:bool; blocker_reasons:tuple[str,...]
    def to_dict(self):
        return {"left_snapshot_id":self.left_snapshot_id,"right_snapshot_id":self.right_snapshot_id,"left_generated_as_of":self.left_generated_as_of,"right_generated_as_of":self.right_generated_as_of,"chronological_order":self.chronological_order,"same_release":self.same_release,"same_implementation_digest":self.same_implementation_digest,"operational_status_change":self.operational_status_change,"readiness_status_change":self.readiness_status_change,"operator_action_change":self.operator_action_change,"evidence_completeness_change":self.evidence_completeness_change,"evidence_freshness_change":self.evidence_freshness_change,"suspension_change":self.suspension_change,"heartbeat_change":self.heartbeat_change,"alert_change":self.alert_change,"acknowledgment_change":self.acknowledgment_change,"recovery_change":self.recovery_change,"blockers_added":list(self.blockers_added),"blockers_removed":list(self.blockers_removed),"component_changes":[{"component":a,"left":b,"right":c} for a,b,c in self.component_changes],"safety_invariants_unchanged":self.safety_invariants_unchanged,"permits_automated_action":False,"live_ready":False,"unattended_ready":False,"blocker_reasons":list(self.blocker_reasons)}

def compare_snapshot_items(left,right):
    a,b=left.snapshot.to_dict(),right.snapshot.to_dict(); common=lambda field:a[field]!=b[field]
    component=tuple((k,a["source_component_statuses"][k],b["source_component_statuses"][k]) for k in sorted(a["source_component_statuses"]) if a["source_component_statuses"][k]!=b["source_component_statuses"][k])
    blockers_added=tuple(sorted(set(b["blocker_reasons"])-set(a["blocker_reasons"]))); blockers_removed=tuple(sorted(set(a["blocker_reasons"])-set(b["blocker_reasons"])))
    order="LEFT_BEFORE_RIGHT" if a["generated_as_of"]<b["generated_as_of"] else "RIGHT_BEFORE_LEFT" if b["generated_as_of"]<a["generated_as_of"] else "SAME_TIME"
    reasons=[] if a["release_commit_sha"]==b["release_commit_sha"] and a["implementation_digest"]==b["implementation_digest"] else ["CROSS_RELEASE_COMPARISON"]
    return SnapshotComparison(left.snapshot_id,right.snapshot_id,a["generated_as_of"],b["generated_as_of"],order,a["release_commit_sha"]==b["release_commit_sha"],a["implementation_digest"]==b["implementation_digest"],common("operational_status"),common("supervised_readiness_status"),common("recommended_operator_action"),common("evidence_completeness"),common("evidence_freshness"),common("suspension_status"),common("heartbeat_status"),common("alert_status"),common("acknowledgment_status"),common("recovery_status"),blockers_added,blockers_removed,component,all(a[x] is False and b[x] is False for x in ("strategy_enabled","activation_approvals_present","protection_grounded","activation_approved","permits_automated_action","live_ready","unattended_ready")),False,False,False,tuple(reasons))
